INSERT INTO `chapters` VALUES
(1, 1, 'Mecanique du Point et du Solide', 'mecanique-point-solide', 'Cinematique, dynamique newtonienne, energetique et oscillateurs mecaniques.', NULL, 'l1', 1, 1, '2026-08-13 21:23:45'),
(2, 1, 'Thermodynamique Statistique & Macroscopique', 'thermodynamique', 'Principes de la thermodynamique, machines thermiques et entropie.', NULL, 'l2', 2, 2, '2026-08-13 21:23:45'),
(3, 1, 'Electromagnetisme dans le vide & les milieux', 'electromagnetisme', 'Equations de Maxwell, ondes electromagnetiques et induction.', NULL, 'l2', 3, 3, '2026-08-13 21:23:45'),
(4, 2, 'Cinetique Chimique & Catalyse', 'cinetique-chimique', 'Vitesses de reaction, lois d ordre et cinetique enzymatique.', NULL, 'l1', 1, 1, '2026-08-13 21:23:45'),
(5, 2, 'Chimie Organique : Mecanismes & Stereochimie', 'chimie-organique', 'Substitution nucleophile, elimination, addition et stereochimie.', NULL, 'l2', 2, 2, '2026-08-13 21:23:45'),
(6, 1, 'Chapitre 1 - Ondes sur une corde vibrante', 'tome-1-ondes-mecaniques-ch1-ondes-sur-une-corde-vibrante', 'Équation d\'Alembert, ondes progressives, réflexions aux limites, modes propres et énergie vibratoire.', 'Tome 1 : Ondes Mécaniques', 'l2', 1, 1, '2026-08-13 22:53:55'),
(7, 1, 'Chapitre 2 - Ondes acoustiques dans un fluide', 'tome-1-ondes-mecaniques-ch2-ondes-acoustiques-dans-un-fluide', 'Propagation acoustique, équations d\'état des fluides, impédance acoustique, énergie et effet Doppler.', 'Tome 1 : Ondes Mécaniques', 'l2', 2, 2, '2026-08-13 22:53:55'),
(8, 1, 'Chapitre 3 - Autres types d\'ondes 1D (Barres, Câbles, Réseaux)', 'tome-1-ondes-mecaniques-ch3-autres-types-d-ondes-1d', 'Ondes longitudinales dans les barres, milieux dispersifs, vitesse de phase et vitesse de groupe.', 'Tome 1 : Ondes Mécaniques', 'l2', 3, 3, '2026-08-13 22:53:55'),
(9, 1, 'Chapitre 4 - Ondes de gravitation dans un liquide (Houle, Vagues)', 'tome-1-ondes-mecaniques-ch4-ondes-de-gravitation-liquide', 'Théorie de la houle, équation d\'onde en eau profonde et peu profonde, dispersion et solitons.', 'Tome 1 : Ondes Mécaniques', 'l2', 4, 4, '2026-08-13 22:53:55'),
(10, 1, 'Chapitre 5 - Diffusion thermique et de particules', 'tome-1-ondes-mecaniques-ch5-diffusion-thermique-et-particules', 'Loi de Fick, équation de la chaleur, régimes stationnaires et sinusoïdaux, marche au hasard.', 'Tome 1 : Ondes Mécaniques', 'l2', 5, 5, '2026-08-13 22:53:55'),
(11, 1, 'Chapitre 1 - Ondes Électromagnétiques dans le vide (OPPM)', 'tome-2-ondes-em-vide-milieux-ch1-oem-dans-le-vide', 'Équations de Maxwell dans le vide, onde plane progressive harmonique, polarisation, vecteur de Poynting et pression de radiation.', 'Tome 2 : Ondes Électromagnétiques dans le Vide et les Milieux', 'l2', 6, 6, '2026-08-13 22:53:55'),
(12, 1, 'Chapitre 2 - Lignes de transmission', 'tome-2-ondes-em-vide-milieux-ch2-lignes-de-transmission', 'Équations des télégraphistes, impédance caractéristique, réflexions et régime sinusoïdal sur ligne.', 'Tome 2 : Ondes Électromagnétiques dans le Vide et les Milieux', 'l2', 7, 7, '2026-08-13 22:53:56'),
(13, 1, 'Chapitre 3 - Conducteurs métalliques et guides d\'ondes', 'tome-2-ondes-em-vide-milieux-ch3-conducteurs-metalliques', 'Effet de peau, réflexion sur un conducteur parfait ou réel, propagation guidée et cavités résonantes.', 'Tome 2 : Ondes Électromagnétiques dans le Vide et les Milieux', 'l2', 8, 8, '2026-08-13 22:53:56'),
(14, 1, 'Chapitre 4 - Ondes électromagnétiques dans un plasma', 'tome-2-ondes-em-vide-milieux-ch4-ondes-dans-un-plasma', 'Modèle d\'Drude-Lorentz, fréquence plasma, propagation et réflexion ionosphérique.', 'Tome 2 : Ondes Électromagnétiques dans le Vide et les Milieux', 'l2', 9, 9, '2026-08-13 22:53:56'),
(15, 1, 'Chapitre 5 - Rayonnement dipolaire et diffusion', 'tome-2-ondes-em-vide-milieux-ch5-rayonnement-dipolaire-diffusion', 'Potentiels retardés, dipôle oscillant de Hertz, puissance rayonnée et diffusion Rayleigh / Thomson.', 'Tome 2 : Ondes Électromagnétiques dans le Vide et les Milieux', 'l2', 10, 10, '2026-08-13 22:53:56'),
(16, 1, 'Chapitre 1 - Introduction aux milieux diélectriques', 'tome-3-ondes-em-dielectriques-ch1-introduction-dielectriques', 'Polarisation de la matière, vecteur déplacement électrique D, polarisabilité moléculaire et condensateurs.', 'Tome 3 : Ondes Électromagnétiques dans les Diélectriques', 'l3', 11, 11, '2026-08-13 22:53:56'),
(17, 1, 'Chapitre 2 - Indice d\'un milieu et dispersion', 'tome-3-ondes-em-dielectriques-ch2-indice-d-un-milieu', 'Modèle de l\'électron lié, formule de Sellmeier, absorption et vitesses de groupe/phase.', 'Tome 3 : Ondes Électromagnétiques dans les Diélectriques', 'l3', 12, 12, '2026-08-13 22:53:56'),
(18, 1, 'Chapitre 3 - Ondes électromagnétiques dans les diélectriques isotropes', 'tome-3-ondes-em-dielectriques-ch3-ondes-dielectriques-isotropes', 'Lois de Snell-Descartes, coefficients de Fresnel, réflexion totale, ondes évanescentes et fibres optiques.', 'Tome 3 : Ondes Électromagnétiques dans les Diélectriques', 'l3', 13, 13, '2026-08-13 22:53:56'),
(19, 1, 'Chapitre 4 - Optique des milieux diélectriques anisotropes', 'tome-3-ondes-em-dielectriques-ch4-dielectriques-anisotropes', 'Tenseur de permittivité, ellipsoïde des indices, biréfringence, lames retardatrices et activité optique.', 'Tome 3 : Ondes Électromagnétiques dans les Diélectriques', 'l3', 14, 14, '2026-08-13 22:53:56'),
(20, 1, 'Chapitre 5 - Diélectriques non linéaires et optique non linéaire', 'tome-3-ondes-em-dielectriques-ch5-dielectriques-non-lineaires', 'Susceptibilité non linéaire, génération de seconde harmonique, effet Kerr et auto-focalisation.', 'Tome 3 : Ondes Électromagnétiques dans les Diélectriques', 'l3', 15, 15, '2026-08-13 22:53:56'),
